import{_ as o,a0 as l,w as p,s as r,I as s,x as n,a1 as i,A as t,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Podman 中運行一個 Linux 虛擬機 | LCTT x X-CMD","titleTemplate":false,"description":"在 Podman 中運行一個 Linux 虛擬機 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Podman 中運行一個 Linux 虛擬機 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Podman 中運行一個 Linux 虛擬機 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210720 Run a Linux virtual machine in Podman","title":"在 Podman 中運行一個 Linux 虛擬機","tag":"202107","desc":""},"relativePath":"202107/20210720 Run a Linux virtual machine in Podman.md","filePath":"[post].md"}'),h={name:"202107/20210720 Run a Linux virtual machine in Podman.md"};function u(m,a,g,c,k,b){const e=l("Link");return p(),r("div",null,[a[23]||(a[23]=s("h1",{id:"在-podman-中運行一個-linux-虛擬機",tabindex:"-1"},[n("在 Podman 中運行一個 Linux 虛擬機 "),s("a",{class:"header-anchor",href:"#在-podman-中運行一個-linux-虛擬機","aria-label":"Permalink to “在 Podman 中運行一個 Linux 虛擬機”"},"​")],-1)),a[24]||(a[24]=s("blockquote",null,[s("p",null,"使用 Podman Machine 創建一個基本的 Fedora CoreOS 虛擬機來使用容器和容器化工作負載。")],-1)),a[25]||(a[25]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202107/31/114043y4d0kstx90zpx6o3.jpg",alt:""})],-1)),s("p",null,[a[1]||(a[1]=n("Fedora CoreOS 是一個自動更新、最小化的基於 ",-1)),i(e,{href:"http://coreos.github.io/rpm-ostree/"},{default:t(()=>[...a[0]||(a[0]=[n("rpm-ostree",-1)])]),_:1}),a[2]||(a[2]=n(" 的操作系統，用於安全地、大規模地運行容器化工作負載。",-1))]),s("p",null,[i(e,{href:"https://github.com/containers/podman"},{default:t(()=>[...a[3]||(a[3]=[n("Podman",-1)])]),_:1}),a[4]||(a[4]=n(" “是一個用於管理容器和鏡像、掛載到這些容器中的卷，以及由這些容器組組成的吊艙的工具。Podman 基於 libpod，它是一個容器生命週期管理庫”。",-1))]),s("p",null,[a[6]||(a[6]=n("當你使用 ",-1)),i(e,{href:"http://docs.podman.io/en/latest/markdown/podman-machine.1.html"},{default:t(()=>[...a[5]||(a[5]=[n("Podman Machine",-1)])]),_:1}),a[7]||(a[7]=n(" 時，神奇的事情發生了，它可以幫助你創建一個基本的 Fedora CoreOS 虛擬機（VM）來使用容器和容器化工作負載。",-1))]),a[26]||(a[26]=d(`<h3 id="開始使用-podman-machine" tabindex="-1">開始使用 Podman Machine <a class="header-anchor" href="#開始使用-podman-machine" aria-label="Permalink to “開始使用 Podman Machine”">​</a></h3><p>第一步是安裝 Podman。如果你已經安裝了最新版本的 Podman，你可以跳過這個步驟。在我的 Fedora 34 機器上，我用以下方式安裝 Podman：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install podman</span></span></code></pre></div><p>我使用的是 podman-3.2.2-1.fc34.x86_64。</p><h3 id="初始化-fedora-coreos" tabindex="-1">初始化 Fedora CoreOS <a class="header-anchor" href="#初始化-fedora-coreos" aria-label="Permalink to “初始化 Fedora CoreOS”">​</a></h3><p>Podman 安裝完成後，用以下方法初始化它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>❯ podman machine init vm2</span></span>
<span class="line"><span>Downloading VM image: fedora-coreos-34.20210626.1.0-qemu.x86_64.qcow2.xz: done </span></span>
<span class="line"><span>Extracting compressed file</span></span></code></pre></div><p>這個命令創建了 <code>vm2</code>，並下載了 .xz 格式的 Fedora CoreOS 的 qcow2 文件並將其解壓。</p><h3 id="列出你的虛擬機" tabindex="-1">列出你的虛擬機 <a class="header-anchor" href="#列出你的虛擬機" aria-label="Permalink to “列出你的虛擬機”">​</a></h3><p>瞭解你的虛擬機和它們的狀態是很重要的，<code>list</code> 命令可以幫助你做到這一點。下面的例子顯示了我所有的虛擬機的名稱，它們被創建的日期，以及它們最後一次啓動的時間：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>❯ podman machine list </span></span>
<span class="line"><span>NAME          VM TYPE     CREATED     LAST UP</span></span>
<span class="line"><span>podman-machine-default* qemu      6 days ago   Currently running</span></span>
<span class="line"><span>vm2           qemu      11 minutes ago 11 minutes ago</span></span></code></pre></div><h3 id="啓動一個虛擬機" tabindex="-1">啓動一個虛擬機 <a class="header-anchor" href="#啓動一個虛擬機" aria-label="Permalink to “啓動一個虛擬機”">​</a></h3><p>要啓動一個虛擬機，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>❯ podman machine start</span></span>
<span class="line"><span>Waiting for VM ...</span></span></code></pre></div><h3 id="ssh-到虛擬機" tabindex="-1">SSH 到虛擬機 <a class="header-anchor" href="#ssh-到虛擬機" aria-label="Permalink to “SSH 到虛擬機”">​</a></h3><p>你可以使用 SSH 來訪問你的虛擬機，並使用它來運行工作負載，而沒有任何麻煩的設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>❯ podman machine ssh  </span></span>
<span class="line"><span>Connecting to vm podman-machine-default. To close connection, use \`~.\` or \`exit\`</span></span>
<span class="line"><span>Fedora CoreOS 34.20210611.1.0</span></span>
<span class="line"><span>Tracker: https://github.com/coreos/fedora-coreos-tracker</span></span>
<span class="line"><span>Discuss: https://discussion.fedoraproject.org/c/server/coreos/</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>Last login: Wed Jun 23 13:23:36 2021 from 10.0.2.2</span></span>
<span class="line"><span>[core@localhost ~]$ uname -a</span></span>
<span class="line"><span>Linux localhost 5.12.9-300.fc34.x86_64 #1 SMP Thu Jun 3 13:51:40 UTC 2021 x86_64 x86_64 x86_64 GNU/Linux</span></span>
<span class="line"><span>[core@localhost ~]$</span></span></code></pre></div><p>目前，Podman 只支持一次運行一個虛擬機。</p><h3 id="停止你的虛擬機" tabindex="-1">停止你的虛擬機 <a class="header-anchor" href="#停止你的虛擬機" aria-label="Permalink to “停止你的虛擬機”">​</a></h3><p>要停止運行中的虛擬機，請使用 <code>stop</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>❯ podman machine stop</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[core@localhost ~]$ Connection to localhost closed by remote host.</span></span>
<span class="line"><span>Connection to localhost closed.</span></span>
<span class="line"><span>Error: exit status 255</span></span></code></pre></div><p>我希望這能幫助你開始使用 Podman Machine。請試一試，並在評論中告訴我們你的想法。</p><hr>`,23)),s("p",null,[a[9]||(a[9]=n("via: ",-1)),i(e,{href:"https://opensource.com/article/21/7/linux-podman"},{default:t(()=>[...a[8]||(a[8]=[n("https://opensource.com/article/21/7/linux-podman",-1)])]),_:1})]),s("p",null,[a[14]||(a[14]=n("作者：",-1)),i(e,{href:"https://opensource.com/users/sumantro"},{default:t(()=>[...a[10]||(a[10]=[n("Sumantro Mukherjee",-1)])]),_:1}),a[15]||(a[15]=n(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...a[11]||(a[11]=[n("lujun9972",-1)])]),_:1}),a[16]||(a[16]=n(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:t(()=>[...a[12]||(a[12]=[n("geekpi",-1)])]),_:1}),a[17]||(a[17]=n(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...a[13]||(a[13]=[n("wxy",-1)])]),_:1})]),s("p",null,[a[20]||(a[20]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[18]||(a[18]=[n("LCTT",-1)])]),_:1}),a[21]||(a[21]=n(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...a[19]||(a[19]=[n("Linux中國",-1)])]),_:1}),a[22]||(a[22]=n(" 榮譽推出",-1))])])}const P=o(h,[["render",u]]);export{C as __pageData,P as default};
